namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns through rigorous logical reasoning." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, rhetoric, and the cultural contexts of the English language." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, societies, and civilizations to understand the human experience." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms, their structure, function, growth, and evolution." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Email = "s.chen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds 3 patents in natural language processing. She received her Ph.D. from MIT." },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Associate Professor", Email = "j.rodriguez@university.edu", Bio = "Dr. Rodriguez focuses on distributed systems and cloud computing. Before joining the university, he spent 8 years at a leading tech company. He is known for his engaging teaching style." },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Professor", Email = "e.watson@university.edu", Bio = "Dr. Watson is a number theorist with a passion for mathematical education. She has authored two widely-used textbooks and received the university's Distinguished Teaching Award three times." },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Assistant Professor", Email = "m.park@university.edu", Bio = "Dr. Park researches quantum mechanics and condensed matter physics. He completed postdoctoral research at CERN and brings real-world experimental insights into his lectures." },
            new() { Id = 5, Name = "Prof. Linda Garcia", Title = "Professor", Email = "l.garcia@university.edu", Bio = "Prof. Garcia is a literary scholar specializing in 19th-century American literature. She has published three books and serves as editor of the University Literary Review." },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Associate Professor", Email = "r.kim@university.edu", Bio = "Dr. Kim is a historian of modern East Asia. His research focuses on cultural exchange and diplomacy in the 20th century. He has received multiple grants for archival research." },
            new() { Id = 7, Name = "Dr. Anna Patel", Title = "Professor", Email = "a.patel@university.edu", Bio = "Dr. Patel is a molecular biologist studying gene regulation in cancer cells. She directs the university's Genomics Research Lab and mentors dozens of graduate students." },
            new() { Id = 8, Name = "Dr. David Liu", Title = "Assistant Professor", Email = "d.liu@university.edu", Bio = "Dr. Liu specializes in algorithms and computational complexity. He is a recipient of the NSF CAREER Award and actively involves undergraduates in his research projects." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science. Topics include problem solving, abstraction, algorithms, data representation, and an introduction to programming using Python. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (lists, stacks, queues, trees, graphs, hash tables) and algorithms (sorting, searching, graph traversal). Emphasis on analyzing time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 8, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 72 },
            new() { Id = 3, Code = "CS 410", Title = "Artificial Intelligence", Description = "Comprehensive overview of AI techniques including search, knowledge representation, planning, machine learning, and neural networks. Includes hands-on projects using modern AI frameworks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Center 112", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 4, Code = "CS 350", Title = "Distributed Systems", Description = "Principles of distributed computing including consensus protocols, replication, fault tolerance, and distributed storage systems. Students build a simplified distributed key-value store.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Center 205", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 41 },

            // Mathematics
            new() { Id = 5, Code = "MATH 151", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Graphical, numerical, and analytical approaches.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 132 },
            new() { Id = 6, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 203", DepartmentId = 2, InstructorId = 3, IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 78 },

            // Physics
            new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Lecture and laboratory components cover Newton's laws, conservation of energy and momentum, rotational dynamics, and oscillations.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 100", DepartmentId = 3, InstructorId = 4, IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 87 },
            new() { Id = 8, Code = "PHYS 320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, quantum states, measurement, angular momentum, and hydrogen atom. Prerequisites: PHYS 201, MATH 250.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Location = "Physics Lab 301", DepartmentId = 3, InstructorId = 4, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 28 },

            // English
            new() { Id = 9, Code = "ENG 110", Title = "College Writing", Description = "Development of critical reading, analytical thinking, and academic writing skills. Students write multiple essays with emphasis on argumentation, evidence, and revision.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Humanities 405", DepartmentId = 4, InstructorId = 5, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 27 },
            new() { Id = 10, Code = "ENG 340", Title = "American Literature: 1850–1920", Description = "Survey of American literary works from the Civil War era through the early twentieth century. Authors include Whitman, Dickinson, Twain, James, and Wharton.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Humanities 302", DepartmentId = 4, InstructorId = 5, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 22 },

            // History
            new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period. Emphasis on cross-cultural interaction and comparative analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Liberal Arts 210", DepartmentId = 5, InstructorId = 6, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 65 },
            new() { Id = 12, Code = "HIST 380", Title = "Modern East Asia", Description = "Political, cultural, and economic history of China, Japan, and Korea from the 19th century to the present. Explores modernization, conflict, and globalization.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Liberal Arts 315", DepartmentId = 5, InstructorId = 6, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 38 },

            // Biology
            new() { Id = 13, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamental principles of biology including cell structure, genetics, evolution, and ecology. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 7, IsFeatured = true, MaxEnrollment = 130, CurrentEnrollment = 110 },
            new() { Id = 14, Code = "BIO 310", Title = "Molecular Biology", Description = "Structure and function of biological macromolecules, gene expression and regulation, DNA replication, and recombinant DNA technology. Prerequisites: BIO 101, CHEM 201.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Life Sciences 245", DepartmentId = 6, InstructorId = 7, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 39 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Instructor> GetInstructors() => _instructors;

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

