@page "/courses"
@rendermode InteractiveServer
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or keyword…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th>Availability</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in filteredCourses)
            {
                var dept = Catalog.GetDepartment(course.DepartmentId);
                var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                <tr>
                    <td><strong>@course.Code</strong></td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td>
                        @if (spotsLeft > 10)
                        {
                            <span class="badge bg-success">@spotsLeft spots</span>
                        }
                        else if (spotsLeft > 0)
                        {
                            <span class="badge bg-warning text-dark">@spotsLeft spots</span>
                        }
                        else
                        {
                            <span class="badge bg-danger">Full</span>
                        }
                    </td>
                    <td>
                        <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @filteredCourses.Count course(s)</p>
}

@code {
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        UpdateResults();
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        selectedDepartmentId = 0;
        UpdateResults();
    }

    protected override void OnParametersSet() => UpdateResults();

    private void UpdateResults()
    {
        filteredCourses = Catalog.SearchCourses(
            searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }
}

@page "/courses/{Id:int}"
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    var dept = Catalog.GetDepartment(course.DepartmentId);
    var instructor = Catalog.GetInstructor(course.InstructorId);
    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;

    <nav aria-label="breadcrumb">
