@page "/courses/{Id:int}"
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    var dept = Catalog.GetDepartment(course.DepartmentId);
    var instructor = Catalog.GetInstructor(course.InstructorId);
    var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="departments/@dept?.Id">@dept?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Schedule &amp; Location</h4>
            <table class="table table-bordered w-auto">
                <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                <tr><th>Location</th><td>@course.Location</td></tr>
                <tr><th>Credits</th><td>@course.Credits</td></tr>
                <tr>
                    <th>Enrollment</th>
                    <td>
                        @course.CurrentEnrollment / @course.MaxEnrollment
                        @if (spotsLeft > 0)
                        {
                            <span class="text-success ms-2">(@spotsLeft spots remaining)</span>
                        }
                        else
                        {
                            <span class="text-danger ms-2">(Full)</span>
                        }
                    </td>
                </tr>
            </table>
        </div>

        <div class="col-md-4">
            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@instructor.Name</h6>
                        <p class="card-text"><em>@instructor.Title</em></p>
                        <p class="card-text">@instructor.Bio</p>
                        <p class="card-text"><small class="text-muted">📧 @instructor.Email</small></p>
                    </div>
                </div>
            }

            <div class="mt-3">
                <a href="enroll?courseId=@course.Id" class="btn btn-success w-100">Enroll in This Course</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/departments"
@inject CatalogService Catalog

<PageTitle>Departments</PageTitle>

<h1>Departments</h1>
<p>Explore academic departments and their course offerings.</p>

<div class="row">
    @foreach (var dept in departments)
    {
        var courses = Catalog.GetCoursesByDepartment(dept.Id);
        <div class="col-md-6 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h4 class="card-title">@dept.Name <span class="badge bg-secondary">@dept.Code</span></h4>
                    <p class="card-text">@dept.Description</p>
                    <p class="text-muted">@courses.Count course(s) offered</p>
                    <a href="departments/@dept.Id" class="btn btn-outline-primary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
    }
}

@page "/departments/{Id:int}"
@inject CatalogService Catalog

<PageTitle>@(department?.Name ?? "Department Not Found")</PageTitle>

@if (department is null)
{
    <div class="alert alert-warning">Department not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active" aria-current="page">@department.Name</li>
        </ol>
    </nav>

    <h1>@department.Name <span class="badge bg-secondary">@department.Code</span></h1>
    <p class="lead">@department.Description</p>

    <h3 class="mt-4">Courses</h3>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses currently offered in this department.</div>
    }
    else
    {
        <div class="row">
            @foreach (var course in courses)
            {
                var instructor = Catalog.GetInstructor(course.InstructorId);
                var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                <div class="col-md-6 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code — @course.Title</h5>
                            <p class="card-text">@course.Description[..Math.Min(course.Description.Length, 150)]…</p>
                            <p class="mb-1"><strong>Instructor:</strong> @instructor?.Name</p>
                            <p class="mb-1"><strong>Schedule:</strong> @course.Schedule</p>
                            <p class="mb-1"><strong>Credits:</strong> @course.Credits</p>
                            <span class="badge @(spotsLeft > 10 ? "bg-success" : spotsLeft > 0 ? "bg-warning text-dark" : "bg-danger")">
                                @(spotsLeft > 0 ? $"{spotsLeft} spots left" : "Full")
                            </span>
                        </div>
                        <div class="card-footer">
                            <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                            <a href="enroll?courseId=@course.Id" class="btn btn-sm btn-success">Enroll</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public int Id { get; set; }

    private Department? department;
    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        department = Catalog.GetDepartment(Id);
        if (department is not null)
        {
            courses = Catalog.GetCoursesByDepartment(department.Id);
        }
    }
}

@page "/enroll"
@inject CatalogService Catalog
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request for a course. You will receive confirmation via your university email.</p>

@if (submitted)
{
    var selectedCourse = Catalog.GetCourse(model.CourseId);
    <div class="alert alert-success">
        <h4>✅ Enrollment Request Submitted</h4>
        <p>
            <strong>@model.StudentName</strong> (ID: @model.StudentId) — your enrollment request for
            <strong>@selectedCourse?.Code @selectedCourse?.Title</strong> has been received.
        </p>
        <p>You will be notified once your enrollment is confirmed.</p>
        <a href="enroll" class="btn btn-outline-primary">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId"
                               placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => model.StudentId" />
                    <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            var dept = Catalog.GetDepartment(course.DepartmentId);
                            <option value="@course.Id">@course.Code — @course.Title (@dept?.Code)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (PreselectedCourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollmentRequest(model);
        submitted = true;
    }
}

